var out = {};
if (msg.deviceCode != null) { out.deviceCode = msg.deviceCode; }
if (msg.deviceTypeId != null) { out.deviceTypeId = msg.deviceTypeId; }
if (msg.functionCode != null) { out.functionCode = msg.functionCode; }

// 解析器把参数输出成 hn_<序号>_<键名>，这里还原成原始键名
for (var k in msg) {
  if (k.indexOf('hn_') !== 0) { continue; }
  var p = k.split('_');
  out[p.slice(2).join('_')] = msg[k];
}

function bit(v, n) { return ((v >> n) & 1); }

// 0x2036 GPS 伪卫星状态
if (out.gpsSvStatus != null) {
  out.svClockAlarm = bit(out.gpsSvStatus, 0);
  out.svBcodeAlarm = bit(out.gpsSvStatus, 1);
  out.svEphValid = bit(out.gpsSvStatus, 2);
  out.svRfAlarm = bit(out.gpsSvStatus, 3);
  out.svTxOn = bit(out.gpsSvStatus, 4);
  out.svChannelAlarm = bit(out.gpsSvStatus, 5);
  out.svFpgaAlarm = bit(out.gpsSvStatus, 6);
}

// 0x0201 授时同步状态（0 正常 / 1 异常）
if (out.timeSyncStatus != null) {
  out.rxWorkAlarm = bit(out.timeSyncStatus, 0);
  out.rxFixAlarm = bit(out.timeSyncStatus, 1);
  out.rxLeapAlarm = bit(out.timeSyncStatus, 2);
  out.timeSyncAlarm = bit(out.timeSyncStatus, 3);
}

// 0x0020 设备类型 ID
if (out.deviceTypeBits != null) {
  out.hasGpsL1 = bit(out.deviceTypeBits, 0);
  out.hasBds = bit(out.deviceTypeBits, 1);
  out.hasGloR1 = bit(out.deviceTypeBits, 2);
  out.hasGal = bit(out.deviceTypeBits, 3);
  out.hasGpsL2 = bit(out.deviceTypeBits, 4);
  out.hasGloR2 = bit(out.deviceTypeBits, 5);
}

return {msg: out, metadata: metadata, msgType: msgType};
